// Package lock reads and writes gremloader.lock: the exact release, asset, URL, size and SHA-256
// of every package for every platform it is used on (plan E.2.3). It is generated by
// `gremloader lock`, committed beside the package file, and `apply --locked` installs exactly what
// it says and nothing else.
//
// The lock is JSON (decided with the user, Q2): it is machine-written, and encoding/json writes
// map keys in sorted order, so regenerating an unchanged lock gives an identical file.
package lock

import (
	"errors"
	"fmt"
	"net/url"
	"regexp"
	"slices"
	"strings"
	"time"

	"github.com/enls/gremloader/internal/jsonfile"
	"github.com/enls/gremloader/internal/paths"
	"github.com/enls/gremloader/internal/platform"
	"github.com/enls/gremloader/internal/source/github"
	"github.com/enls/gremloader/internal/ver"
)

// SchemaVersion is the lock format this build writes and understands.
const SchemaVersion = 1

// File is gremloader.lock.
type File struct {
	SchemaVersion int                 `json:"schema_version"`
	GeneratedBy   string              `json:"generated_by"`
	GeneratedAt   time.Time           `json:"generated_at"`
	Packages      map[string]*Package `json:"packages"`
}

// Package is one locked release.
type Package struct {
	Repo        string            `json:"repo"`
	Tag         string            `json:"tag"`
	Version     string            `json:"version"`
	PublishedAt *time.Time        `json:"published_at,omitempty"`
	Platforms   map[string]*Asset `json:"platforms"`
}

// Asset is the file installed on one platform.
type Asset struct {
	Asset  string `json:"asset"`
	URL    string `json:"url"`
	SHA256 string `json:"sha256"`
	Size   int64  `json:"size"`
}

// ErrNotLocked: the lock has no entry for that package or platform.
var ErrNotLocked = errors.New("not in the lock file")

// New returns an empty lock stamped with the generating program and time (UTC, whole seconds,
// so the file does not change by a nanosecond count on every run).
func New(generatedBy string, at time.Time) *File {
	return &File{
		SchemaVersion: SchemaVersion,
		GeneratedBy:   generatedBy,
		GeneratedAt:   at.UTC().Truncate(time.Second),
		Packages:      map[string]*Package{},
	}
}

// Load reads path. found is false when there is no lock file.
func Load(path string) (f *File, found bool, err error) {
	f = &File{}
	found, err = jsonfile.Read(path, SchemaVersion, f)
	if err != nil || !found {
		return nil, found, err
	}
	if f.Packages == nil {
		f.Packages = map[string]*Package{}
	}
	if err := f.Validate(); err != nil {
		return nil, true, fmt.Errorf("%s: %w: %w", path, jsonfile.ErrCorrupt, err)
	}
	return f, true, nil
}

// Save validates f and writes it atomically.
func Save(path string, f *File) error {
	if err := f.Validate(); err != nil {
		return fmt.Errorf("refusing to write %s: %w", path, err)
	}
	f.SchemaVersion = SchemaVersion
	return jsonfile.Write(path, f)
}

// Get returns what the lock says to install for pkg on p.
func (f *File) Get(pkg string, p platform.Platform) (*Package, *Asset, error) {
	lp := f.Packages[pkg]
	if lp == nil {
		return nil, nil, fmt.Errorf("package %s: %w", pkg, ErrNotLocked)
	}
	a := lp.Platforms[p.String()]
	if a == nil {
		return nil, nil, fmt.Errorf("package %s on %s: %w (locked for: %s)", pkg, p, ErrNotLocked, strings.Join(lp.platformNames(), ", "))
	}
	return lp, a, nil
}

func (p *Package) platformNames() []string {
	var out []string
	for k := range p.Platforms {
		out = append(out, k)
	}
	slices.Sort(out)
	return out
}

var sha256Hex = regexp.MustCompile(`^[0-9a-f]{64}$`)

// Validate checks every field the installer will trust.
func (f *File) Validate() error {
	var errs []error
	bad := func(format string, a ...any) { errs = append(errs, fmt.Errorf(format, a...)) }
	for name, p := range f.Packages {
		if !paths.ValidPackageName(name) {
			bad("package name %q is not valid", name)
			continue
		}
		if p == nil {
			bad("package %s: empty entry", name)
			continue
		}
		if !github.ValidRepo(p.Repo) {
			bad("package %s: repo %q is not owner/name", name, p.Repo)
		}
		if !ver.ValidTag(p.Tag) {
			bad("package %s: tag %q is not valid", name, p.Tag)
		}
		if _, err := ver.Parse(p.Version); err != nil {
			bad("package %s: version: %v", name, err)
		}
		if len(p.Platforms) == 0 {
			bad("package %s: no platforms", name)
		}
		for key, a := range p.Platforms {
			if _, err := platform.Parse(key); err != nil {
				bad("package %s: %v", name, err)
				continue
			}
			if a == nil {
				bad("package %s on %s: empty entry", name, key)
				continue
			}
			if err := a.validate(); err != nil {
				bad("package %s on %s: %v", name, key, err)
			}
		}
	}
	slices.SortFunc(errs, func(a, b error) int { return strings.Compare(a.Error(), b.Error()) })
	return errors.Join(errs...)
}

func (a *Asset) validate() error {
	var errs []error
	if !validFileName(a.Asset) {
		errs = append(errs, fmt.Errorf("asset %q is not a file name", a.Asset))
	}
	if !sha256Hex.MatchString(a.SHA256) {
		errs = append(errs, errors.New("sha256 is not 64 lower-case hex digits"))
	}
	if a.Size <= 0 {
		errs = append(errs, fmt.Errorf("size %d is not positive", a.Size))
	}
	// Which hosts may be contacted is the download policy's decision, made again at install time;
	// here only the shape is checked. http is allowed so tests can lock against a local server.
	u, err := url.Parse(a.URL)
	switch {
	case err != nil:
		errs = append(errs, fmt.Errorf("url: %w", err))
	case u.Scheme != "https" && u.Scheme != "http", u.Host == "":
		errs = append(errs, fmt.Errorf("url %q is not an http(s) URL", a.URL))
	case u.User != nil:
		errs = append(errs, errors.New("url carries credentials"))
	case u.RawQuery != "" || u.Fragment != "":
		// A signed CDN URL expires and is a credential of sorts: the lock stores the stable
		// release download URL, never where it redirected to.
		errs = append(errs, errors.New("url has a query or fragment (store the release download URL, not a CDN link)"))
	}
	return errors.Join(errs...)
}

func validFileName(s string) bool {
	if s == "" || len(s) > 255 || s == "." || s == ".." || strings.ContainsAny(s, `/\:`) {
		return false
	}
	for _, r := range s {
		if r < 0x20 || r == 0x7f {
			return false
		}
	}
	return true
}
